using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using TownOfHost;using TownOfHost.Modules;using TownOfHost.Roles.Core;using TownOfHost.Roles.Impostor;using UnityEngine;
static partial class Program {
 static void StopRole(Nova n)=>typeof(Nova).GetMethod("Stop",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(n,null);
 static bool Active(Nova n)=>Get<bool>(n,"charging")||Get<bool>(n,"waiting")||Get<bool>(n,"beaming");
 static void OutfitFailureTests(){
 Test("native PlayerName read failure cannot escape preparation or charge",()=>{var n=N();PlayerControl.LocalPlayer.Data.DefaultOutfit.ThrowNameRead=true;Warm(n);Press(n);Check(Get<bool>(n,"charging")&&PlayerControl.LocalPlayer.Data.DefaultOutfit.NameReads==0);StopRole(n);Check(!Active(n));});
 Test("solo host Nova can charge fire and clear the guide",()=>{var n=N(0);PlayerControl.LocalPlayer=n.Player;Start(n);Lock(n);Fire(n);Check(CustomNetObject.Names.Any(x=>x.Contains("rotate=")));Tick(Time.time+1.51f,n);Check(!Active(n)&&CustomNetObject.AllObjects.All(x=>!(x.PlayerControl?.cosmetics?.nameText.text?.Contains("★")??false)));});
 Test("charge display OOM retires guide and restores speed immediately",()=>{var n=N();Warm(n);var tiles=Get<List<NovaBeamTile>>(n,"tiles");var pc=tiles[0].PlayerControl;CustomNetObject.ThrowAppearance=true;Press(n);Check(!Active(n)&&tiles[0].Failed&&!CustomNetObject.AllObjects.Contains(tiles[0])&&pc.cosmetics.nameText.text=="");Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);});
 Test("beam display OOM cannot produce invisible damage or retain guide",()=>{var n=N();Start(n);Lock(n);P(2,x:2);CustomNetObject.ThrowAppearance=true;Tick(Time.time+1.01f,n);Check(!Active(n)&&CustomRoleManager.Attempts==0);foreach(var t in Get<List<NovaBeamTile>>(n,"tiles"))Check(t.PlayerControl==null||!t.PlayerControl.cosmetics.nameText.text.Contains("★"));});
 Test("failed blank update removes a previously visible star without outfit-dependent cleanup",()=>{var n=N();Start(n);var tile=Get<List<NovaBeamTile>>(n,"tiles")[0];var pc=tile.PlayerControl;Check(pc.cosmetics.nameText.text.Contains("★"));CustomNetObject.ThrowAppearance=true;StopRole(n);Check(tile.Failed&&pc.cosmetics.nameText.text==""&&!CustomNetObject.AllObjects.Contains(tile));});
 Test("a retired tile is not retried every update",()=>{var n=N();Start(n);CustomNetObject.ThrowAppearance=true;StopRole(n);int names=CustomNetObject.Names.Count,attempts=CustomNetObject.VisualAttempts;for(int i=0;i<50;i++)Tick(Time.time+.02f,n);Check(CustomNetObject.Names.Count==names&&CustomNetObject.VisualAttempts==attempts&&!Active(n));});
 Test("meeting cleanup works even when host native strings are unreadable",()=>{var n=N();Start(n);PlayerControl.LocalPlayer.Data.DefaultOutfit.ThrowNameRead=true;n.OnStartMeeting();Check(!Active(n)&&CustomNetObject.AllObjects.Count==0);});
 Test("role destruction cleans every tile after a display failure",()=>{var n=N();Start(n);CustomNetObject.ThrowAppearance=true;n.OnDestroy();Check(!Active(n)&&CustomNetObject.AllObjects.Count==0);});
 Test("two Nova pools keep cleanup independent after one visual failure",()=>{var a=N(1);var b=N(2);Warm(a,b);Press(a);CustomNetObject.ThrowAppearance=true;StopRole(a);CustomNetObject.ThrowAppearance=false;Check(Press(b)==false&&Get<bool>(b,"charging"));a.OnDestroy();Check(Get<bool>(b,"TilesReady"));StopRole(b);});
 Test("settings restore failure cannot strand the guide or restoration lease",()=>{var n=N();Start(n);var pc=Get<List<NovaBeamTile>>(n,"tiles")[0].PlayerControl;n.Player.ThrowDirtySettings=true;StopRole(n);Check(!Active(n)&&!pc.cosmetics.nameText.text.Contains("★")&&Get<float>(n,"savedSpeed")<0);});
 Test("obsolete wall probe failure cannot interrupt the penetrating beam",()=>{var n=N();Start(n);var target=P(2,x:8);Lock(n);PhysicsHelpers.Block=(_,_,_,_)=>throw new InvalidOperationException("wall queries must not be used");Fire(n);Check(Active(n)&&!target.IsAlive());Tick(Time.time+1.51f,n);Check(!Active(n)&&Get<List<NovaBeamTile>>(n,"tiles").All(t=>t.PlayerControl==null||!t.PlayerControl.cosmetics.nameText.text.Contains("★")));});
 Test("three normal shots reuse pools and always hide guide at completion",()=>{var n=N();for(int i=0;i<3;i++){Start(n);Lock(n);Fire(n);Tick(Time.time+1.51f,n);Check(!Active(n));Tick(Get<float>(n,"readyAt")+.01f,n);}Check(Get<bool>(n,"TilesReady"));});
 }
}
